{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Hydroxysafflor yellow A, a highly polar glycosylated flavonoid, reached 1026 ng/g in rat brain, directly demonstrating that this structural class can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Camellianin B, a flavonoid glycoside, was detected in rat brain after oral administration, showing that glycosylated flavonoids can cross the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Vidarabine, a sugar-containing nucleoside, achieved CSF-to-plasma ratios of 35–66% in humans, supporting meaningful CNS access for polar glycoside-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Danshensu, a polar catechol-containing acid, crosses the BBB in rats despite being a P-glycoprotein efflux substrate, indicating that efflux liability does not preclude meaningful CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is luteolin 7-O-glucoside, a polar glycosylated flavonoid. Direct brain detection in closely related glycosylated flavonoids (hydroxysafflor yellow A, camellianin B) and in sugar-containing nucleosides, all with high assay-transfer scores, provides convergent evidence for meaningful CNS access despite high polarity. Therefore predict pass.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for luteolin-7-O-glucoside itself.",
    "Extent of brain exposure relative to plasma and the role of transporters or efflux are not quantified for the query.",
    "Possible in vivo deglycosylation to luteolin aglycone could contribute to observed CNS effects."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

